// One structured line per nightly run — the record of whether the batch job did
// its job, queryable in the log aggregator alongside everything else.
const rollup = $('Roll up every tenant').first().json;
const purge = $input.first().json;

const summary = {
  level: rollup.error || purge.error ? 'error' : 'info',
  message: 'Nightly analytics and retention run',
  businesses_rolled_up: rollup.businesses_rolled_up ?? 0,
  rollup_error: rollup.error?.message ?? null,
  purge_result: purge.result ?? null,
  purge_error: purge.error?.message ?? null,
  execution_id: $execution.id,
};

console.log(JSON.stringify(summary));
return [{ json: summary }];
